"""Robot Framework interface module."""

import logging
from pathlib import Path
from typing import Union, List
from pprint import pformat
from taf.rfrl.utilities.parsers.pcap_checker.checker import Checker, AwaitedMessage, PACKET
from taf.rfrl.utilities.parsers.pcap_checker.robot_parser import Tokenizer, Parser
from taf.rfrl.utilities.parsers.pcap_checker.utils import PcapProvider


class pcap_checker:
    """
    PCAP Checker is solution to verify flow of messages in PCAP file.
    It provides Robot Framework and Python APIs.

    Usage in Robot Framework:

    .. code:: robotframework

        *** Settings ***
        Library  pcap_checker

        *** Variables ***
        ${attach_cell_id}=  111
        ${pcap_file_path}=  ${CURDIR}${/}attach_nsa.pcap

        # You have to define flow of expected messages
        # ...
        # SgNBAdditionRequestAcknowledge {  <- it is message's name (you can type here anything, it is just for you)
        #   findBy {  <- 'findBy' section contains inspectors to identify packet (you can add other inspectors)
        #     has(x2ap.SgNBAdditionRequestAcknowledge_element)  <- 'has()' inspector (or inspectors) checks if packet
        #                                                          contains given key or value
        #   }
        #   verifyBy {  <-'verifyBy' section verifies if found packet fits your requirements
        #     has(nr-rrc.physCellId:=${attach_cell_id})  <- in this case 'has()' inspector (or inspectors) checks
        #                                                   if packet contains nr-rrc.physCellId field with value
        #                                                   equals to ${attach_cell_id} variable value
        #   }
        # } <- brackets are very important, you can justify your message and its content by white chars
        # ...
        ${awaited_messages}=
        ...                   SgNBAdditionRequest {
        ...                     findBy { has(x2ap.SgNBAdditionRequest_element) }
        ...                   }
        ...                   SgNBAdditionRequestAcknowledge {
        ...                     findBy { has(x2ap.SgNBAdditionRequestAcknowledge_element) }
        ...                     verifyBy { has(nr-rrc.physCellId:=${attach_cell_id}) }
        ...                   }
        ...                   SgNBReconfigurationComplete {
        ...                     findBy { has(x2ap.SgNBReconfigurationComplete_element) }
        ...                   }
        ...                   SNStatusTransfer {
        ...                     findBy { has(x2ap.SNStatusTransfer_element) }
        ...                   }
        ${forbidden_messages}=
        ...                   SgNBModificationRequest {
        ...                     findBy { has(x2ap.SgNBModificationRequest_element) }
        ...                     verifyBy { has(nr-rrc.scgFailureInfo_element) }
        ...                   }
        ${sn_status_transfer_messages}=
        ...                   SNStatusTransfer {
        ...                     findBy { has(x2ap.SNStatusTransfer_element) }
        ...                   }

        *** Test Cases ***
        Demo
            # 'Expect Flow' keyword checks if there are packets in order indicated by above definition in PCAP
            pcap_checker.Expect Flow        pcap_file=${pcap_file_path}
            ...                             display_filter=x2ap  # filter pcap before analysis (filter as in wireshark)
            ...                             awaited_messages=${awaited_messages}
            ...                             forbidden_messages=${forbidden_messages}  # if there will be one forbidden
            #                                                                           message verification failed

            # 'Get Packets' keyword returns expected packet (or packets if there many packets will be matched)
            ${packets}=  pcap_checker.Get Packets        pcap_file=${pcap_file_path}
            ...                                          display_filter=x2ap
            ...                                          awaited_message=${sn_status_transfer_messages}
            Log  ${packets}  # For processing

            # 'Count Packets' counts expected packets in PCAP file
            ${packets}=  pcap_checker.Count Packets      pcap_file=${pcap_file_path}
            ...                                          display_filter=x2ap
            ...                                          awaited_message=${sn_status_transfer_messages}
            Log  Count of SNStatusTransfer messages: ${packets}

    Usage in Python:

    .. code:: python

        import pathlib
        from pcap_checker import Checker, AwaitedMessage, inspectors, PcapProvider


        attach_cell_id = 111
        pcap_file_path = pathlib.Path(__file__).parent.resolve() / 'attach_nsa.pcap'

        # You have to define flow of expected messages:
        awaited_messages = [
            AwaitedMessage(
                name='SgNBAdditionRequest',
                find_by=[inspectors.HasInspector('x2ap.SgNBAdditionRequest_element')]
            ),
            AwaitedMessage(
                name='SgNBAdditionRequestAcknowledge',
                find_by=[inspectors.HasInspector('x2ap.SgNBAdditionRequestAcknowledge_element')],
                verify_by=[inspectors.HasInspector('nr-rrc.physCellId', str(attach_cell_id))]
            ),
            AwaitedMessage(
                name='SgNBReconfigurationComplete',
                find_by=[inspectors.HasInspector('x2ap.SgNBReconfigurationComplete_element')]
            ),
            AwaitedMessage(
                name='SNStatusTransfer',
                find_by=[inspectors.HasInspector('x2ap.SNStatusTransfer_element')]
            ),
        ]

        forbidden_messages = [
            AwaitedMessage(
                name='SgNBModificationRequest',
                find_by=[inspectors.HasInspector('x2ap.SgNBModificationRequest_element')],
                verify_by=[inspectors.HasInspector('nr-rrc.scgFailureInfo_element')]
            ),
        ]


        pcap_provider = PcapProvider()
        checker = Checker(pcap_provider=pcap_provider)
        checker.expect_flow(pcap_file=pcap_file_path,
                            display_filter='x2ap',
                            awaited_messages=awaited_messages,
                            forbidden_messages=forbidden_messages)

        print('NO ERROR')

    """

    def __init__(self):

        self._tokenizer = Tokenizer()
        self._parser = Parser()
        self._pcap_analyzer = PcapProvider()
        self._checker = Checker(self._pcap_analyzer)

    def expect_flow(self, pcap_file: Union[str, Path], display_filter: str,
                    awaited_messages: str, forbidden_messages: Union[str, None] = None) -> None:
        """
        Expects given flow of messages in pcap file.

        :param display_filter: filter expression (wireshark format)
        :param pcap_file: path to PCAP file
        :param awaited_messages: list of expected messages in text format, e.g:
        '''
            SgNBAdditionRequest { findBy { has(x2ap.SgNBAdditionRequest_elemenlt) } }
            SgNBAdditionRequestAcknowledge { findBy { has(x2ap.SgNBAdditionRequestAcknowledge_element) }
                                           verifyBy { has(nr-rrc.physCellId:=${attach_cell_id}) } }
        '''
        :param forbidden_messages: list of forbidden messages in text format like above
        :return: None
        """

        if forbidden_messages is not None:
            forbidden_messages = self._parse_text_messages(forbidden_messages, 'Parsed forbidden messages')
        else:
            forbidden_messages = []

        awaited_messages = self._parse_text_messages(awaited_messages, 'Parsed awaited messages')

        self._checker.expect_flow(pcap_file, display_filter, awaited_messages, forbidden_messages)

    def get_packets(self, pcap_file: Union[str, Path], display_filter: str, awaited_message: str) -> List[PACKET]:
        """
        Returns all packets which were found in PCAP file based on given query.

        :param display_filter: filter expression (wireshark format)
        :param pcap_file: path to PCAP file
        :param awaited_message: definition of expected message in text format, e.g:
        '''
        SgNBAdditionRequest { findBy { has(x2ap.SgNBAdditionRequest_elemenlt) } }
        '''
        :return: list of packets matched to given format
        """

        awaited_message = self._parse_text_messages(awaited_message, 'Parsed awaited message')

        if len(awaited_message) != 1:
            raise ValueError('Exactly one awaited message must be provided.')

        return self._checker.get_packets(pcap_file, display_filter, awaited_message[0])

    def count_packets(self, pcap_file: Union[str, Path], display_filter: str, awaited_message: str) -> int:
        """
        Returns number of all packets which were found in PCAP file based on given query.

        :param display_filter: filter expression (wireshark format)
        :param pcap_file: path to PCAP file
        :param awaited_message: definition of expected message in text format, e.g:
        '''
        SgNBAdditionRequest { findBy { has(x2ap.SgNBAdditionRequest_elemenlt) } }
        '''
        :return: number of packets matched to given format
        """

        awaited_message = self._parse_text_messages(awaited_message, 'Parsed awaited message')

        if len(awaited_message) != 1:
            raise ValueError('Exactly one awaited message must be provided.')

        return self._checker.count_packets(pcap_file, display_filter, awaited_message[0])

    def _parse_text_messages(self, text: str, log_info: str) -> List[AwaitedMessage]:
        """Parses given text to messages list."""

        tokens = self._tokenizer.tokenize(text)
        messages = self._parser.parse(tokens)

        logging.debug('%s:\n%s', log_info, pformat(messages))

        return messages
